INSERT INTO community_posts (id, board_type, title, content, user_id, view_count, like_count, comment_count, is_hidden, is_deleted, created_at, updated_at) VALUES
(11, '자유게시판', '요즘 홍대 합주실 대여비 너무 비싸지 않나요? ㅠㅠ', '예전엔 1시간에 만원대면 충분했는데 요새는 기본이 2만원이 넘어가네요.. 다들 어디로 다니시나요?', 12, 21, 11, 2, b'0', b'0', '2026-06-03 01:36:15', '2026-06-03 01:36:15'),
(12, '자유게시판', '어제 펜타포트 락 페스티벌 다녀오신 분? 슬램존 역대급 ㅋㅋㅋ', '진짜 미친듯이 놀다 왔습니다. 어제 깃발 들고 계셨던 분 계신가요?', 10, 69, 2, 2, b'0', b'0', '2026-06-12 18:33:06', '2026-06-12 18:33:06'),
(13, '자유게시판', '직장인 밴드 회식 메뉴 추천 좀요', '매번 삼겹살만 먹으니까 질리네요. 합주 끝나고 가기 좋은 메뉴 뭐 있을까요?', 14, 6, 2, 2, b'0', b'0', '2026-06-11 00:42:42', '2026-06-11 00:42:42'),
(14, '자유게시판', '이번 주말에 뮬(Mule) 직거래하러 갑니다', '꾹꾹이 페달 하나 건지러 대전까지 가네요. 제발 상태 좋았으면!', 7, 93, 16, 2, b'0', b'0', '2026-06-10 15:22:27', '2026-06-10 15:22:27'),
(15, '자유게시판', '요즘 밴드 음악 추천 좀 해주세요', '맨날 듣던 것만 들어서 질리네요. 브릿팝이나 얼터너티브 쪽으로 숨은 명곡 있을까요?', 9, 64, 16, 2, b'0', b'0', '2026-06-02 20:38:35', '2026-06-02 20:38:35'),
(16, '자유게시판', '메트로놈 앱 어떤 거 쓰시나요?', '무료 앱 쓰는데 자꾸 광고 떠서 짜증나네요 ㅠㅠ', 14, 83, 1, 2, b'0', b'0', '2026-06-11 10:24:09', '2026-06-11 10:24:09'),
(17, '자유게시판', '공연장 대관료 질문드립니다', '100명 규모 클럽 대관하려고 하는데 보통 주말 저녁이면 얼마 정도 하나요?', 4, 2, 19, 2, b'0', b'0', '2026-06-06 15:17:53', '2026-06-06 15:17:53'),
(18, '자유게시판', '오아시스 재결합 진짜인가요? ㄷㄷ', '루머만 돌더니 이번엔 진짜라는 기사가 떴네요. 내한 오면 무조건 갑니다.', 10, 25, 4, 2, b'0', b'0', '2026-06-10 01:05:55', '2026-06-10 01:05:55'),
(19, '자유게시판', '밴드 이름 짓기 너무 어렵네요', '3주째 아이디어만 내고 결정을 못하고 있습니다. 다들 밴드 이름 어떻게 지으셨나요?', 12, 94, 15, 2, b'0', b'0', '2026-06-10 15:54:48', '2026-06-10 15:54:48'),
(20, '자유게시판', '비오는 날 합주하러 가기 너무 귀찮음', '이펙터 보드 들고 우산 쓰고 가려니 벌써부터 막막하네요.', 5, 18, 12, 2, b'0', b'0', '2026-06-13 00:58:27', '2026-06-13 00:58:27'),
(21, '자유게시판', '우리 밴드 보컬이 갑자기 탈퇴한다고 합니다..', '다음 달이 공연인데 갑자기 잠수타버렸네요. 멘붕입니다.', 4, 45, 1, 2, b'0', b'0', '2026-06-03 18:31:54', '2026-06-03 18:31:54'),
(22, '자유게시판', '기타줄 어떤 브랜드 주로 쓰시나요?', '맨날 다다리오만 쓰다가 엘릭서로 넘어가볼까 고민 중입니다.', 9, 7, 8, 2, b'0', b'0', '2026-06-13 11:53:50', '2026-06-13 11:53:50'),
(23, '자유게시판', '유튜브에 커버 영상 올리려는데 저작권 문제 없나요?', '수익 창출은 안 할 건데 그냥 올려도 되는지 궁금합니다.', 11, 94, 1, 2, b'0', b'0', '2026-06-13 06:15:20', '2026-06-13 06:15:20'),
(24, '자유게시판', '베이시스트 구하기가 하늘의 별따기네요', '기타랑 드럼은 넘쳐나는데 베이스가 없어서 합주를 못하고 있습니다 ㅠㅠ', 7, 8, 0, 2, b'0', b'0', '2026-06-07 12:16:57', '2026-06-07 12:16:57'),
(25, '자유게시판', '공연 포스터 직접 만드시나요?', '포토샵 할 줄 아는 멤버가 없어서 걱정이네요.', 13, 26, 19, 2, b'0', b'0', '2026-06-10 21:53:40', '2026-06-10 21:53:40'),
(26, '자유게시판', '요즘 릴스에 뜨는 밴드들 진짜 실력 좋네요', '보면서 반성 많이 하고 갑니다. 연습하러 가야지..', 14, 89, 1, 1, b'0', b'0', '2026-06-04 00:24:12', '2026-06-04 00:24:12'),
(27, '자유게시판', '앰프 시뮬레이터 vs 진짜 앰프', '라이브 할 때 무겁게 앰프 들고 다니기 벅차서 쿼드코어텍스 같은 거 고민 중입니다.', 10, 93, 12, 2, b'0', b'0', '2026-06-06 15:50:45', '2026-06-06 15:50:45'),
(28, '자유게시판', '기타 솔로 연습 꿀팁 있나요?', '크로매틱만 주구장창 하려니 지루해서 미치겠습니다.', 9, 85, 16, 1, b'0', b'0', '2026-06-10 14:55:46', '2026-06-10 14:55:46'),
(29, '자유게시판', '이번 주 홍대 클럽 공연 라인업 미쳤네요', '롤링홀 라인업 보셨나요? 이번 주말은 여기로 정했습니다.', 7, 59, 2, 1, b'0', b'0', '2026-06-09 21:59:02', '2026-06-09 21:59:02'),
(30, '자유게시판', '다들 밴드 연습 말고 개인 연습은 얼마나 하시나요?', '직장 다니면서 하루에 1시간 내기도 힘드네요 ㅠㅠ', 4, 41, 13, 2, b'0', b'0', '2026-06-09 08:14:35', '2026-06-09 08:14:35'),
(31, '고민상담', '보컬이 고음이 안 올라가서 고민입니다. 계속 해도 될까요?', '밴드 시작 6개월차인데 2옥 라만 넘어도 목이 조여옵니다.. 보컬 바꿀까요?', 7, 52, 3, 2, b'0', b'0', '2026-06-08 08:44:54', '2026-06-08 08:44:54'),
(32, '고민상담', '베이스 치는데 손가락 물집이 안 사라져요..', '슬랩 연습하면서 물집이 계속 터집니다. 원래 이런가요?', 12, 10, 16, 2, b'0', b'0', '2026-06-03 12:26:00', '2026-06-03 12:26:00'),
(33, '고민상담', '밴드 내에 연애하는 멤버가 생겼습니다', '기타랑 키보드가 비밀 연애하다 걸렸는데, 깨지면 밴드 터질까봐 조마조마하네요.', 10, 47, 3, 2, b'0', b'0', '2026-06-11 18:55:17', '2026-06-11 18:55:17'),
(34, '고민상담', '드럼 치는데 박자감이 너무 안 좋아요', '메트로놈 켜고 연습해도 합주만 들어가면 빨라집니다. 드러머 자격이 없는 걸까요?', 14, 8, 8, 2, b'0', b'0', '2026-06-07 06:34:12', '2026-06-07 06:34:12'),
(35, '고민상담', '자작곡을 쓰고 싶은데 화성학을 꼭 알아야 하나요?', '코드는 대충 치는데 이론을 하나도 몰라서 진행이 뻔해집니다.', 9, 75, 1, 2, b'0', b'0', '2026-06-03 16:33:39', '2026-06-03 16:33:39'),
(36, '고민상담', '직장인 밴드, 합주 불참하는 멤버 어떻게 할까요?', '야근 핑계 대면서 한 달에 두 번이나 빠지는 멤버가 있는데 내보내야 할까요?', 4, 60, 3, 2, b'0', b'0', '2026-06-09 21:57:56', '2026-06-09 21:57:56'),
(37, '고민상담', '30대 중반, 뒤늦게 기타 시작해도 될까요?', '어릴 때 로망이었는데 이제야 여유가 생기네요. 손이 굳었을까 걱정입니다.', 11, 59, 3, 2, b'0', b'0', '2026-06-07 17:38:37', '2026-06-07 17:38:37'),
(38, '고민상담', '장비병 걸린 것 같습니다. 통장 잔고가 남아나질 않아요', '멀티이펙터 샀다가 아날로그가 좋아보여서 또 사고.. 미치겠네요.', 5, 47, 4, 2, b'0', b'0', '2026-06-04 06:37:20', '2026-06-04 06:37:20'),
(39, '고민상담', '무대 공포증이 너무 심합니다. 손이 덜덜 떨려요', '연습 땐 완벽한데 무대만 올라가면 머리가 하얘지고 박자가 나갑니다. 극복 방법 있을까요?', 7, 80, 13, 2, b'0', b'0', '2026-06-08 19:27:02', '2026-06-08 19:27:02'),
(40, '고민상담', '베이스 라인을 어떻게 짜야 할지 감이 안 옵니다', '루트음만 치려니 너무 밋밋한데, 어프로치 노트를 넣으면 곡이랑 따로 노네요.', 12, 60, 16, 2, b'0', b'0', '2026-06-06 05:56:42', '2026-06-06 05:56:42'),
(41, '고민상담', '밴드 탈퇴하고 싶은데 어떻게 말해야 상처를 안 줄까요?', '음악적 성향이 너무 달라서 스트레스인데, 형 동생 하는 사이라 말하기가 어렵네요.', 9, 73, 18, 2, b'0', b'0', '2026-06-09 13:54:53', '2026-06-09 13:54:53'),
(42, '고민상담', '보컬 톤이 너무 평범해서 고민입니다', '노래방 가면 노래 잘한다는 소린 듣는데, 밴드 음악엔 묻히는 밋밋한 목소리예요.', 10, 72, 6, 1, b'0', b'0', '2026-06-03 08:54:11', '2026-06-03 08:54:11'),
(43, '고민상담', '혼자 믹싱하는데 저음역대가 자꾸 뭉칩니다', '베이스랑 킥 드럼이 서로 부딪혀서 소리가 지저분해요. EQ 만져도 똑같네요.', 13, 65, 5, 1, b'0', b'0', '2026-06-07 17:14:36', '2026-06-07 17:14:36'),
(44, '고민상담', '일렉기타 입문하려는데 레스폴 vs 스트랫 추천 부탁드려요', '디자인은 레스폴인데, 범용성은 스트랫이라 그래서 며칠째 고민 중입니다.', 11, 21, 17, 2, b'0', b'0', '2026-06-03 00:32:47', '2026-06-03 00:32:47'),
(45, '고민상담', '메인기타리스트랑 자꾸 의견 충돌이 납니다', '저는 리듬 위주로 가고 싶은데 메인기타는 자꾸 속주만 하려고 하네요.', 4, 15, 1, 1, b'0', b'0', '2026-06-06 16:44:34', '2026-06-06 16:44:34'),
(46, '고민상담', '드럼 소리가 너무 커서 보컬 모니터링이 안 돼요', '좁은 합주실이라 드럼 소리에 보컬이 다 먹힙니다. 대책이 있을까요?', 10, 34, 5, 1, b'0', b'0', '2026-06-10 23:12:24', '2026-06-10 23:12:24'),
(47, '고민상담', '밴드 홍보는 보통 어떻게 하시나요?', '인스타 계정 파긴 했는데 팔로워가 안 늘어요 ㅠㅠ', 12, 41, 10, 1, b'0', b'0', '2026-06-13 07:59:33', '2026-06-13 07:59:33'),
(48, '고민상담', '커버곡 위주로 하다가 자작곡 밴드로 넘어가려니 힘드네요', '합주 속도도 안 나고 다들 열정이 식어가는 느낌입니다.', 5, 14, 3, 1, b'0', b'0', '2026-06-07 01:27:38', '2026-06-07 01:27:38'),
(49, '고민상담', '건반 연주자인데 합주 때 소리가 자꾸 기타에 묻힙니다', '볼륨을 키워도 소리가 안 뚫고 나오는 느낌이에요.', 9, 46, 1, 1, b'0', b'0', '2026-06-05 20:33:13', '2026-06-05 20:33:13'),
(50, '고민상담', '멤버 구하기 너무 지쳐서 원맨 밴드 하려고 합니다', '로직 깔아서 미디로 다 찍고 기타만 제가 치려는데 한계가 많을까요?', 7, 0, 2, 1, b'0', b'0', '2026-06-11 20:00:29', '2026-06-11 20:00:29'),
(51, '악기자랑', '큰맘 먹고 펜더 커스텀샵 스트라토캐스터 장만했습니다!! 🎸', '3년 적금 부어서 데려왔습니다. 레릭 처리 예술이네요. 오늘 밤은 안고 잡니다 ㅋㅋ', 5, 62, 7, 2, b'0', b'0', '2026-06-07 12:03:06', '2026-06-07 12:03:06'),
(52, '악기자랑', '황학동에서 업어온 빈티지 롤랜드 신디사이저 수리 완료!', '헐값에 주워와서 한달 동안 부품 구하고 납땜해서 살려냈습니다. 소리 팻하네요!', 13, 19, 13, 2, b'0', b'0', '2026-06-10 07:43:41', '2026-06-10 07:43:41'),
(53, '악기자랑', '제 첫 페달보드 완성했습니다!', '튜너-드라이브-코러스-딜레이-리버브 국민 세팅으로 맞췄습니다. 무거워 죽겠네요.', 9, 50, 18, 2, b'0', b'0', '2026-06-10 09:22:57', '2026-06-10 09:22:57'),
(54, '악기자랑', '드디어 내 방에 방음부스 설치했습니다 ㅠㅠ', '아파트에서 눈치보며 전자드럼 치다가 드디어 1.5x1.5 부스 넣었습니다. 천국이네요.', 14, 2, 16, 2, b'0', b'0', '2026-06-11 07:45:56', '2026-06-11 07:45:56'),
(55, '악기자랑', '깁슨 레스폴 스탠다드 골드탑 샀어요!!', '슬래쉬 톤 내보고 싶어서 질렀습니다. 허리 부러질 거 같은데 소리는 미쳤네요.', 10, 52, 14, 1, b'0', b'0', '2026-06-09 22:46:45', '2026-06-09 22:46:45'),
(56, '악기자랑', '마틴 어쿠스틱 D-28 영입 완료!', '기타치면 누구나 종착역은 마틴이라더니 쳐보고 바로 긁었습니다. 스트로크 소리가 다르네요.', 7, 17, 5, 1, b'0', b'0', '2026-06-07 13:35:59', '2026-06-07 13:35:59'),
(57, '악기자랑', '커스텀 베이스 주문 제작 6개월만에 수령했습니다', '바디 목재부터 픽업까지 전부 제 취향으로 때려넣었습니다. 네크 그립감 최고네요.', 12, 81, 2, 1, b'0', b'0', '2026-06-04 23:18:18', '2026-06-04 23:18:18'),
(58, '악기자랑', '이펙터 보드 테트리스 끝판왕 인증합니다', '페달트레인 나노에 꾸역꾸역 6개 우겨넣었습니다. 발로 밟기 빡세긴 하네요 ㅋㅋ', 5, 64, 15, 1, b'0', b'0', '2026-06-09 00:27:37', '2026-06-09 00:27:37'),
(59, '악기자랑', '질전 K 커스텀 심벌 세트 질렀어요 ㅠㅠ', '텅장이 되었지만 영롱한 자태를 보니 배가 부릅니다. 내일 합주가 기대되네요.', 14, 44, 12, 1, b'0', b'0', '2026-06-13 04:21:34', '2026-06-13 04:21:34'),
(60, '악기자랑', '낡은 스콰이어 기타 락카로 커스텀 도색해봤습니다', '어차피 싼 기타라 망치면 버린다는 마인드로 칠했는데 나름 펑크하고 이쁘네요!', 11, 17, 12, 1, b'0', b'0', '2026-06-13 00:57:14', '2026-06-13 00:57:14'),
